from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + skill[i]

        stack = []
        for i in range(n):
            mi = -P[i]
            ci = P[i + 1]

            while len(stack) >= 2:
                m_top, c_top = stack[-1]
                m_prev, c_prev = stack[-2]

                left_side = (ci - c_top) * (m_prev - m_top)
                right_side = (c_top - c_prev) * (m_top - mi)

                if left_side >= right_side:
                    stack.pop()
                else:
                    break

            stack.append((mi, ci))

        S = 0
        for j in range(1, m):
            left = 0
            right = len(stack) - 1

            while left < right:
                mid = (left + right) // 2
                m_mid, c_mid = stack[mid]
                m_next, c_next = stack[mid + 1]

                v_mid = m_mid * mana[j] + c_mid * mana[j - 1]
                v_next = m_next * mana[j] + c_next * mana[j - 1]

                if v_mid <= v_next:
                    left = mid + 1
                else:
                    right = mid

            S += stack[left][0] * mana[j] + stack[left][1] * mana[j - 1]

        return S + P[n] * mana[-1]
